// signClass lives here, not in view.go, so Tailwind (which scans templ output only) keeps the classes.
func signClass(s sign, neutral string) string {
	switch s {
	case signGain:
		return "text-emerald-400"
	case signLoss:
		return "text-rose-400"
	default:
		return neutral
	}
}

